create temporary view    fx_rate_${grass_region_without_quote}
as
select  grass_date
        ,grass_region
        ,first(exchange_rate) as exchange_rate
from    mp_order.dim_exchange_rate__reg_s0_live
where   grass_date = ${local_date}
  and   grass_region = ${grass_region}
group by 1, 2
;

--sql_divide_splitter--
cache   table dim_ads_${grass_region_without_quote} options ('storageLevel' 'MEMORY_AND_DISK_SER' ) as
SELECT ads_id, placement, main_product_type, product_type,sub_product_type
       ,CASE WHEN COALESCE(ads_id, -1) IN (-1, 0) THEN CONCAT(CAST(COALESCE(ads_id, -1) AS STRING), '_', CAST(FLOOR(RAND() * 20) AS STRING))
             ELSE CAST(COALESCE(ads_id, -1) AS STRING)
             END AS salted_ads_id
FROM (
    SELECT ads_id, placement, main_product_type, product_type,sub_product_type,
           ROW_NUMBER() OVER (PARTITION BY ads_id ORDER BY placement DESC) AS rn
    FROM mp_paidads.dim_advertise__reg_s0_live
    WHERE tz_type = 'local'
      AND grass_region = ${grass_region}
      AND grass_date = ${local_date}
) t
WHERE rn = 1
;

--sql_divide_splitter--
cache   table dwd_ads_${grass_region_without_quote} options ('storageLevel' 'MEMORY_AND_DISK_SER' ) as
select  user_id
        ,request_id
        ,item_id
        ,max(placement) as placement
from    mp_paidads.dwd_advertise_performance_di__reg_s0_live
where   tz_type = 'local'
  and   grass_region = ${grass_region}
  and   grass_date = ${local_date}
  and   placement = 40
group by 1, 2, 3
;

--sql_divide_splitter--
create temporary view   tmp_dwd_paidads_detail_${grass_region_without_quote}
as
select  grass_region
        ,user_id
        ,entrance
        ,placement
        ,ads_id
        ,case   when item_id IS NULL THEN -1
                ELSE item_id
         end as item_id
        ,case   when location IS NULL THEN -1
                ELSE location
         end as location
        ,impression_cnt
        ,click_cnt
        ,order_cnt
        ,ads_order_gmv_local
        ,expenditure_amt_local
        ,broad_gmv_amt_local
        ,case   when page_type = 'home' and page_section = 'daily_discover' and target_type = 'item' then 'item card'
                when page_type = 'home' and page_section = 'daily_discover' and target_type = 'item_mix_feed_card' then 'mix feed card'
                when page_type = 'home' and page_section = 'daily_discover' and target_type = 'video' then 'video card'
                else 'others'
         end as card_type
from    mp_paidads.dwd_advertise_performance_di__reg_s0_live
where   grass_date = ${local_date}
  and   grass_region = ${grass_region}
  and   tz_type = 'local'
  and   user_id > 0
  and   entrance IN (3, 31, 32, 4, 8, 9, 10, 11)
;

--sql_divide_splitter--
create temporary view   paidads_part_results_${grass_region_without_quote}
as
select  grass_region
        ,user_id
        ,item_id
        ,common_feature
        ,type
        ,location
        ,is_roi2
        ,ads_id
        ,card_type
        ,SUM(impression_cnt) AS impression_cnt
        ,SUM(click_cnt) AS click_cnt
        ,SUM(order_cnt) AS order_cnt
        ,SUM(ads_direct_gmv_usd) AS ads_direct_gmv_usd
        ,SUM(ads_broad_gmv_usd) AS ads_broad_gmv_usd
        ,SUM(ads_revenue_usd) AS ads_revenue_usd
from    (
    select  T1.grass_region
            ,user_id
            ,entrance
            ,placement
            ,common_feature
            ,type
            ,ads_id
            ,case   when placement = 40 THEN 1
                    ELSE 0
             end as is_roi2
            ,item_id
            ,location
            ,impression_cnt
            ,click_cnt
            ,order_cnt
            ,ads_order_gmv_local / exchange_rate AS ads_direct_gmv_usd
            ,broad_gmv_amt_local / exchange_rate AS ads_broad_gmv_usd
            ,expenditure_amt_local / exchange_rate AS ads_revenue_usd
            ,card_type
    from    (
        select  *
                ,case   when entrance IN (3, 31, 32) THEN 'Daily Discover'
                        when entrance = 4 THEN 'You May Also Like'
                        when entrance = 8 THEN 'Cart Recommendation'
                        when entrance = 9 THEN 'Order Successful Recommendation'
                        when entrance = 10 THEN 'Order Detail Page Recommendation'
                        when entrance = 11 THEN 'My Purchase Page Recommendation'
                        ELSE 'Others'
                 end as common_feature
                ,'all' AS type
        from    tmp_dwd_paidads_detail_${grass_region_without_quote}
        union all
        select  *
                ,'Daily Discover' AS common_feature
                ,case   when entrance = 3 THEN 'external'
                        when entrance = 31 THEN 'mixfeed_internal_organic_entrance'
                        when entrance = 32 THEN 'mixfeed_internal_ads_entrance'
                        ELSE 'Others'
                 end as type
        from    tmp_dwd_paidads_detail_${grass_region_without_quote}
        where   entrance  IN (3, 31, 32)
    ) AS T1
    left join fx_rate_${grass_region_without_quote} as T2
    on      T1.grass_region = T2.grass_region
)
where   common_feature <> 'Others'
group by 1, 2, 3, 4, 5, 6, 7, 8, 9
;

