cache   table ad_item_${grass_region_without_quote} options ('storageLevel' 'MEMORY_AND_DISK_SER' ) as
select  case    when item_id is null then -1
                else item_id
        end as item_id
        ,entrance
from    mp_paidads.dwd_advertise_performance_di__reg_s0_live
where   grass_date = ${local_date}
  and   grass_region = ${grass_region}
  and   tz_type = 'local'
  and   user_id > 0
  and   entrance in (4, 3, 25, 31, 32, 8, 9, 10, 11)
  and   impression_cnt > 0
group by 1, 2
having  item_id <> -1
;

--sql_divide_splitter--
cache   table dwd_advertise_performance_${grass_region_without_quote} options ('storageLevel' 'MEMORY_AND_DISK_SER') as
select  T1.grass_region
        ,user_id
        ,search_entrance
        ,item_id
        ,case   when location is null then -1
                else location
         end as location
        ,case   when placement = 40 then 1
                else 0
         end is_roi2
        ,ads_id
        ,expenditure_amt_local / exchange_rate as ads_revenue_usd
        ,ads_order_gmv_local /exchange_rate as ads_direct_gmv_usd
        ,broad_gmv_amt_local /exchange_rate as ads_broad_gmv_usd
        ,card_type
from    (
    select  grass_date
            ,grass_region
            ,user_id
            ,search_entrance
            ,item_id
            ,location
            ,placement
            ,ads_id
            ,case   when page_type = 'home' and page_section = 'daily_discover' and target_type = 'item' then 'item card'
                    when page_type = 'home' and page_section = 'daily_discover' and target_type = 'item_mix_feed_card' then 'mix feed card'
                    when page_type = 'home' and page_section = 'daily_discover' and target_type = 'video' then 'video card'
                    else 'others'
             end as card_type
            ,sum(expenditure_amt_local) as expenditure_amt_local
            ,sum(ads_order_gmv_local) as ads_order_gmv_local
            ,sum(broad_gmv_amt_local) as broad_gmv_amt_local
    from    mp_paidads.dwd_advertise_performance_di__reg_s0_live
    where   grass_date = ${local_date}
      and   grass_region = ${grass_region}
      and   tz_type = 'local'
      and   user_id > 0
      and   entrance = 1
      and   search_entrance in('homepage_dd_card', 'cart_ymal_card', 'mpp_ymal_card', 'osp_ymal_card', 'pdp_ymal_card')
      and   (
                    COALESCE(expenditure_amt_local, 0) > 0
                or  COALESCE(ads_order_gmv_local, 0) > 0
                or  COALESCE(broad_gmv_amt_local, 0) > 0
            )
    group by 1, 2, 3, 4, 5, 6, 7, 8, 9
) as T1
left join fx_rate_${grass_region_without_quote} as T2
on      T1.grass_region = T2.grass_region
  and   T1.grass_date = T2.grass_date
;

