            ,common_feature
            ,type
            ,location
            ,is_roi2
            ,main_product_type
            ,product_type
            ,sub_product_type
            ,card_type
            ,0 as omni_entry_impr_ads_cnt
            ,0 as omni_entry_impr_organic_cnt
            ,0 as omni_entry_impr_cnt
            ,0 as omni_entry_click_ads_cnt
            ,0 as omni_entry_click_organic_cnt
            ,0 as omni_entry_click_cnt
            ,omni_item_impr_ads_cnt
            ,omni_item_impr_organic_cnt
            ,omni_item_impr_cnt
            ,omni_item_click_ads_cnt
